import java.util.Arrays;

public final class FloydWarshallTest {
    private FloydWarshallTest() {
    }

    public static void main(String[] args) {
        computesShortestPaths();
        doesNotMutateInput();
        detectsNegativeCycles();
        rejectsInvalidMatrices();
        rejectsInvalidFormatterMatrices();
        throwsOnDistanceOverflow();
        formatsUnreachableDistances();

        System.out.println("All FloydWarshall tests passed.");
    }

    private static void computesShortestPaths() {
        assertMatrixEquals(
            ExampleGraphs.weightedDirectedGraphShortestPaths(),
            FloydWarshall.shortestPaths(ExampleGraphs.weightedDirectedGraph())
        );
    }

    private static void doesNotMutateInput() {
        int inf = FloydWarshall.NO_PATH;
        int[][] graph = {
            {0, 2, inf},
            {inf, 0, 3},
            {inf, inf, 0}
        };

        int[][] original = Matrices.copyOf(graph);
        FloydWarshall.shortestPaths(graph);

        assertMatrixEquals(original, graph);
    }

    private static void detectsNegativeCycles() {
        int inf = FloydWarshall.NO_PATH;
        int[][] graph = {
            {0, 1, inf},
            {inf, 0, -2},
            {-2, inf, 0}
        };

        int[][] distances = FloydWarshall.shortestPaths(graph);
        assertTrue(FloydWarshall.hasNegativeCycle(distances), "Expected a negative cycle.");
    }

    private static void rejectsInvalidMatrices() {
        assertThrows(IllegalArgumentException.class, () -> FloydWarshall.shortestPaths(null));
        assertThrows(
            IllegalArgumentException.class,
            () -> FloydWarshall.shortestPaths(new int[][] {{0}, {1, 0}})
        );
        assertThrows(
            IllegalArgumentException.class,
            () -> FloydWarshall.shortestPaths(new int[][] {{0}, null})
        );
        assertThrows(
            IllegalArgumentException.class,
            () -> FloydWarshall.shortestPaths(new int[][] {{0, 1}})
        );
    }

    private static void rejectsInvalidFormatterMatrices() {
        assertThrows(IllegalArgumentException.class, () -> DistanceMatrixFormatter.format(null));
        assertThrows(
            IllegalArgumentException.class,
            () -> DistanceMatrixFormatter.format(new int[][] {{0}, {1, 0}})
        );
    }

    private static void throwsOnDistanceOverflow() {
        int inf = FloydWarshall.NO_PATH;
        int[][] graph = {
            {0, Integer.MAX_VALUE - 1, inf},
            {inf, 0, 2},
            {inf, inf, 0}
        };

        assertThrows(ArithmeticException.class, () -> FloydWarshall.shortestPaths(graph));
    }

    private static void formatsUnreachableDistances() {
        int inf = FloydWarshall.NO_PATH;
        int[][] distances = {
            {0, inf},
            {inf, 0}
        };

        String lineSeparator = System.lineSeparator();
        String expected = "0 INF" + lineSeparator + "INF 0" + lineSeparator;
        assertEquals(expected, DistanceMatrixFormatter.format(distances));
    }

    private static void assertMatrixEquals(int[][] expected, int[][] actual) {
        if (!Arrays.deepEquals(expected, actual)) {
            throw new AssertionError(
                "Expected " + Arrays.deepToString(expected) + " but was " + Arrays.deepToString(actual)
            );
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    private static void assertEquals(String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("Expected \"" + expected + "\" but was \"" + actual + "\"");
        }
    }

    private static void assertThrows(Class<? extends Throwable> expectedType, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (expectedType.isInstance(error)) {
                return;
            }
            throw new AssertionError(
                "Expected " + expectedType.getSimpleName() + " but caught " + error.getClass().getSimpleName(),
                error
            );
        }

        throw new AssertionError("Expected " + expectedType.getSimpleName() + " to be thrown.");
    }
}

import java.util.Arrays;

final class Matrices {
    private Matrices() {
    }

    static int requireSquare(int[][] matrix, String label) {
        int columnCount = requireRectangular(matrix, label);
        if (matrix.length != columnCount) {
            throw new IllegalArgumentException(label + " must be square.");
        }
        return matrix.length;
    }

    static int requireRectangular(int[][] matrix, String label) {
        if (matrix == null) {
            throw new IllegalArgumentException(label + " must not be null.");
        }

        if (matrix.length == 0) {
            return 0;
        }

        if (matrix[0] == null) {
            throw new IllegalArgumentException(label + " must not contain null rows.");
        }

        int columnCount = matrix[0].length;
        for (int rowIndex = 1; rowIndex < matrix.length; rowIndex++) {
            if (matrix[rowIndex] == null) {
                throw new IllegalArgumentException(label + " must not contain null rows.");
            }
            if (matrix[rowIndex].length != columnCount) {
                throw new IllegalArgumentException(label + " must be rectangular.");
            }
        }

        return columnCount;
    }

    static int[][] copyOf(int[][] matrix) {
        requireRectangular(matrix, "Matrix");

        int[][] copy = new int[matrix.length][];
        for (int rowIndex = 0; rowIndex < matrix.length; rowIndex++) {
            copy[rowIndex] = Arrays.copyOf(matrix[rowIndex], matrix[rowIndex].length);
        }

        return copy;
    }
}

public final class FloydWarshall {
    public static final int NO_PATH = Integer.MAX_VALUE;
    public static final int INF = NO_PATH;

    private FloydWarshall() {
    }

    public static int[][] shortestPaths(int[][] graph) {
        int vertexCount = Matrices.requireSquare(graph, "Graph matrix");
        int[][] distances = Matrices.copyOf(graph);

        for (int via = 0; via < vertexCount; via++) {
            for (int from = 0; from < vertexCount; from++) {
                for (int to = 0; to < vertexCount; to++) {
                    relax(distances, from, via, to);
                }
            }
        }

        return distances;
    }

    public static boolean hasNegativeCycle(int[][] distances) {
        Matrices.requireSquare(distances, "Distance matrix");

        for (int index = 0; index < distances.length; index++) {
            if (distances[index][index] < 0) {
                return true;
            }
        }

        return false;
    }

    public static boolean isReachable(int distance) {
        return distance != NO_PATH;
    }

    private static void relax(int[][] distances, int from, int via, int to) {
        if (!canRelax(distances, from, via, to)) {
            return;
        }

        int candidateDistance = pathDistanceThrough(distances, from, via, to);
        if (candidateDistance < distances[from][to]) {
            distances[from][to] = candidateDistance;
        }
    }

    private static boolean canRelax(int[][] distances, int from, int via, int to) {
        return isReachable(distances[from][via]) && isReachable(distances[via][to]);
    }

    private static int pathDistanceThrough(int[][] distances, int from, int via, int to) {
        return addDistances(distances[from][via], distances[via][to]);
    }

    private static int addDistances(int left, int right) {
        try {
            return Math.addExact(left, right);
        } catch (ArithmeticException exception) {
            throw new ArithmeticException("Path distance overflowed int range.");
        }
    }
}

